-- docs.make_list v2: toggle bullets or numbers, type each item, then prove the caller-computed word count in the count dialog.
-- Counts survive Docs autocapitalization, which rewrites words but never their number.

select public.opera_register_workflow(
  'docs.make_list',
  $wf${"steps":[{"id":"wordsRequired","type":"if","condition":{"op":"not_exists","left":{"$ref":"input.expectedWords"}},"then":[{"id":"noWords","type":"fail","code":"WORDS_REQUIRED","message":"make_list needs input.expectedWords like Words 5."}],"else":[]},{"id":"toggleBullets","type":"if","condition":{"op":"eq","left":{"$ref":"input.kind"},"right":"bullet"},"then":[{"id":"bulletBurst","type":"command","method":"browser.burst","params":{"tabId":{"$ref":"input.tabId"},"steps":[{"action":"key","key":"8","modifiers":["control","shift"]}]}}],"else":[]},{"id":"toggleNumbers","type":"if","condition":{"op":"eq","left":{"$ref":"input.kind"},"right":"number"},"then":[{"id":"numberBurst","type":"command","method":"browser.burst","params":{"tabId":{"$ref":"input.tabId"},"steps":[{"action":"key","key":"7","modifiers":["control","shift"]}]}}],"else":[]},{"id":"itemsLoop","type":"foreach","items":{"$ref":"input.items"},"itemVar":"item","steps":[{"id":"typeBurst","type":"command","method":"browser.burst","params":{"tabId":{"$ref":"input.tabId"},"steps":[{"action":"key","text":{"$concat":[{"$ref":"vars.item"},"\n"]}}]}}]},{"id":"countOpen","type":"command","method":"browser.burst","params":{"tabId":{"$ref":"input.tabId"},"steps":[{"action":"key","key":"C","modifiers":["control","shift"]}]}},{"id":"countRead","type":"command","method":"page.read","params":{"tabId":{"$ref":"input.tabId"},"limit":2000,"maxElements":10}},{"id":"countClose","type":"command","method":"browser.burst","params":{"tabId":{"$ref":"input.tabId"},"steps":[{"action":"key","key":"Escape"}]}},{"id":"countProve","type":"if","condition":{"op":"contains","left":{"$ref":"steps.countRead.result.page.text"},"right":{"$ref":"input.expectedWords"}},"then":[],"else":[{"id":"countMiss","type":"fail","code":"WORDS_MISSING","message":"Word count does not show the expected words."}]}],"output":{"expected":{"$ref":"input.items"},"verified":true,"count":{"$ref":"input.items"},"words":{"$ref":"input.expectedWords"}}}$wf$,
  'Toggle a list, type each item, and prove the caller-computed word count in the count dialog.',
  true
);
